363	        if (this.registrationDate == null) {
364	            return null;
365	        }
366	        return String.format("FY%02d", fiscalYear(this.registrationDate) % 100);
367	    }
368	
369	    /** The numeric membership level (1-4) mapped from membership points: 1 for 0-1 points, 2 for
370	     *  2-3, 3 for 4-5, and 4 for 6 or more. */
371	    private static int membershipLevel(int points) {
372	        if (points >= 6) {
373	            return 4;
374	        }
375	        if (points >= 4) {
376	            return 3;
377	        }
378	        if (points >= 2) {
379	            return 2;
380	        }
381	        return 1;
382	    }
383	
384	    /** The membership {@code level} held down to {@code cap}, i.e. the smaller of the two, when a cap
385	     *  is present; the level unchanged when {@code cap} is {@code null} and no ceiling applies. */
386	    private static int capMembershipLevel(int level, Integer cap) {
387	        return cap == null ? level : Math.min(level, cap);
388	    }
389	
390	    /**
391	     * The owner's preferred contact channel, derived on read: {@code "EMAIL"} when an email is
392	     * present, otherwise {@code "PHONE"}.
393	     */
394	    @Transient
395	    public String getContactPreference() {
396	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
397	    }
398	
399	    /**
400	     * The owner's age band, derived on read from the {@link #birthDate} relative to the
401	     * {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and
402	     * {@code "SENIOR"} at 65 or over. Returns {@code null} when no birth date (or no registration
403	     * date to measure against) is available.
404	     */
405	    @Transient
406	    public String getAgeBand() {
407	        if (this.birthDate == null || this.registrationDate == null) {
408	            return null;
409	        }
410	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
411	        if (age < 18) {
412	            return "MINOR";
413	        }
414	        if (age < 65) {
415	            return "ADULT";
416	        }
417	        return "SENIOR";
418	    }
419	
420	    /**
421	     * The single Luhn check digit (0-9) computed over the decimal digits contained in the
422	     * {@link #customerCode}, derived on read.
423	     */
424	    @Transient
425	    public Integer getCheckDigit() {
426	        return luhnCheckDigit(this.customerCode);
427	    }
428	
429	    /** Region -> inclusive 4-digit postcode range {low, high}, used to derive the region from the
430	     *  postcode ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
431	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
432	        "NSW", new int[] {2000, 2099},
433	        "VIC", new int[] {3000, 3099},
434	        "QLD", new int[] {4000, 4099});
435	
436	    /**
437	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
438	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
439	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
440	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
441	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
442	     */
443	    @Transient
444	    public String getRegion() {
445	        String byPostcode = regionForPostcode(this.postcode);
446	        if (byPostcode != null) {
447	            return byPostcode;
448	        }
449	        if ("Sydney".equals(this.city)) {
450	            return "NSW";
451	        }
452	        if ("Melbourne".equals(this.city)) {
453	            return "VIC";
454	        }
455	        if ("Brisbane".equals(this.city)) {
456	            return "QLD";
457	        }
458	        return "UNKNOWN";
459	    }
460	
461	    /**
462	     * The owner's locality, derived on read from the region-and-hash {@link #getCustomerCode()
463	     * customer code}: the region segment before the first '-' of the customer code
464	     * ('<REGION>-<HASH8>'). Falls back to the owner's {@link #getRegion() region} when no customer
465	     * code has been assigned yet.
466	     */
467	    @Transient
468	    public String getLocality() {
469	        if (this.customerCode != null) {
470	            int dash = this.customerCode.indexOf('-');
471	            if (dash > 0) {
472	                return this.customerCode.substring(0, dash);
473	            }
474	        }
475	        return getRegion();
476	    }
477	
478	    /** Region -> IANA timezone name, the fixed region-to-timezone table ({@code NSW ->
479	     *  Australia/Sydney}, {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
480	    private static final Map<String, String> REGION_TIMEZONES = Map.of(
481	        "NSW", "Australia/Sydney",
482	        "VIC", "Australia/Melbourne",
483	        "QLD", "Australia/Brisbane");
484	
485	    /**
486	     * The owner's timezone, derived on read as the IANA name for the owner's
487	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table
488	     * ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
489	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region carries no entry in
490	     * the table (e.g. {@code UNKNOWN}).
491	     */
492	    @Transient
493	    public String getTimezone() {
494	        return timezoneForRegion(getLocality());
495	    }
496	
497	    /** The IANA timezone name for {@code region} via the fixed region-to-timezone table, or
498	     *  {@code null} when the region carries no entry ({@code NSW -> Australia/Sydney},
499	     *  {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). */
500	    public static String timezoneForRegion(String region) {
501	        return REGION_TIMEZONES.get(region);
502	    }
503	
504	    /** The inclusive 4-digit postcode {@code {low, high}} range for {@code region}, or {@code null} when
505	     *  the region carries no range rule (i.e. {@code UNKNOWN} or any region absent from the table:
506	     *  {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). */
507	    public static int[] postcodeRangeForRegion(String region) {
508	        return REGION_POSTCODE_RANGES.get(region);
509	    }
510	
511	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
512	     *  absent, not a 4-digit value, or in no known range. */
513	    private static String regionForPostcode(String postcode) {
514	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
515	            return null;
516	        }
517	        int value = Integer.parseInt(postcode);
518	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
519	            int[] range = entry.getValue();
520	            if (value >= range[0] && value <= range[1]) {
521	                return entry.getKey();
522	            }
523	        }
524	        return null;
525	    }
526	
527	    /** Telephone country code -> the national-number length it requires ({@code +61} Australia => 9
528	     *  digits, {@code +1} NANP => 10), used to derive telephone values from the stored E.164 number.
529	     *  The country codes here carry no conflicting prefixes ({@code +61} does not start with
530	     *  {@code +1}), so a number matches at most one. */
531	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
532	        "+61", 9, "+1", 10);
533	
534	    /**
535	     * The stored E.164 {@link #telephone} formatted for humans, derived on read: the country code, a
536	     * space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}). Falls back
537	     * to the raw value when it is {@code null} or begins with no recognised country code.
538	     */
539	    @Transient
540	    public String getTelephoneDisplay() {
541	        if (this.telephone == null) {
542	            return null;
543	        }
544	        String countryCode = countryCodeOf(this.telephone);
545	        if (countryCode == null) {
546	            return this.telephone;
547	        }
548	        String national = this.telephone.substring(countryCode.length());
549	        StringBuilder grouped = new StringBuilder(countryCode);
550	        for (int i = 0; i < national.length(); i++) {
551	            if (i % 3 == 0) {
552	                grouped.append(' ');
553	            }
554	            grouped.append(national.charAt(i));
555	        }
556	        return grouped.toString();
557	    }
558	
559	    /** The recognised telephone country code that {@code telephone} begins with (e.g. {@code "+61"}),
560	     *  or {@code null} when it is {@code null} or begins with no recognised country code. */
561	    public static String countryCodeOf(String telephone) {
562	        if (telephone == null) {
563	            return null;
564	        }
565	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet()) {
566	            if (telephone.startsWith(countryCode)) {
567	                return countryCode;
568	            }
569	        }
570	        return null;
571	    }
572	
573	    /** The national-number length required for {@code countryCode}, or {@code null} when the country
574	     *  code carries no length rule (i.e. any code absent from the table: {@code +61 => 9},
575	     *  {@code +1 => 10}). */
576	    public static Integer nationalNumberLength(String countryCode) {
577	        return NATIONAL_NUMBER_LENGTHS.get(countryCode);
578	    }
579	
580	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
581	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
582	     *  digit-free value yields {@code 0}. */
583	    private static int luhnCheckDigit(String value) {
584	        int sum = 0;
585	        boolean doubling = true;
586	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
587	            char c = value.charAt(i);
588	            if (c < '0' || c > '9') {
589	                continue;
590	            }
591	            int digit = c - '0';
592	            if (doubling) {
593	                digit *= 2;
594	                if (digit > 9) {
595	                    digit -= 9;
596	                }
597	            }
598	            sum += digit;
599	            doubling = !doubling;
600	        }
601	        return (10 - (sum % 10)) % 10;
602	    }
603	
604	    /** The upper-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters; the
605	     *  upper-case rendering of {@link #sha256HexLower(String)}. */
606	    public static String sha256Hex(String input) {
607	        return sha256HexLower(input).toUpperCase(Locale.ROOT);
608	    }
609	
610	    /** The lower-case hex SHA-256 of the UTF-8 bytes of {@code input}, as 64 hex characters. */
611	    public static String sha256HexLower(String input) {
612	        try {
613	            byte[] digest = MessageDigest.getInstance("SHA-256")
614	                .digest(input.getBytes(StandardCharsets.UTF_8));
615	            StringBuilder sb = new StringBuilder(digest.length * 2);
616	            for (byte b : digest) {
617	                sb.append(String.format("%02x", b));
618	            }
619	            return sb.toString();
620	        }
621	        catch (NoSuchAlgorithmException e) {
622	            throw new IllegalStateException("SHA-256 not available", e);
623	        }
624	    }
625	
626	    protected Set<Pet> getPetsInternal() {
627	        if (this.pets == null) {
628	            this.pets = new HashSet<>();
629	        }
630	        return this.pets;
631	    }
632	
633	    protected void setPetsInternal(Set<Pet> pets) {
634	        this.pets = pets;
635	    }
636	
637	    public List<Pet> getPets() {
638	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
639	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
640	        return Collections.unmodifiableList(sortedPets);
641	    }
642	
643	    public void setPets(List<Pet> pets) {
644	        this.pets = new HashSet<>(pets);
645	    }
646	
647	    public void addPet(Pet pet) {
648	        getPetsInternal().add(pet);
649	        pet.setOwner(this);
650	    }
651	
652	    /**
653	     * Return the Pet with the given name, or null if none found for this Owner.
654	     *
655	     * @param name to test
656	     * @return true if pet name is already in use
657	     */
658	    public Pet getPet(String name) {
659	        return getPet(name, false);
660	    }
661	
662	    /**
663	     * Return the Pet with the given name, or null if none found for this Owner.
664	     *
665	     * @param name to test
666	     * @return true if pet name is already in use
667	     */
668	    public Pet getPet(String name, boolean ignoreNew) {
669	        name = name.toLowerCase();
670	        for (Pet pet : getPetsInternal()) {
671	            if (!ignoreNew || !pet.isNew()) {
672	                String compName = pet.getName();
673	                compName = compName.toLowerCase();
674	                if (compName.equals(name)) {
675	                    return pet;
676	                }
677	            }
678	        }
679	        return null;
680	    }
681	
682	    public Pet getPet(Integer petId) {
683	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
684	    }
685	
686	    @Override
687	    public String toString() {
688	        return new ToStringCreator(this)
689	
690	            .append("id", this.getId())
691	            .append("new", this.isNew())
692	            .append("lastName", this.getLastName())
693	            .append("firstName", this.getFirstName())
694	            .append("address", this.address)
695	            .append("city", this.city)
696	            .append("telephone", this.telephone)
697	            .toString();
698	    }
699	}
