62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /** Dedicated audit logger; a successful create emits one line here. */
70	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
71	
72	    /** Request header carrying the client-supplied key that makes a create idempotent. */
73	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
74	
75	    /**
76	     * Idempotency-Key -> id of the owner originally created under that key. A repeat create carrying an
77	     * already-seen key returns that owner rather than creating a duplicate. Only successful creates are
78	     * recorded here, and the key space is client-supplied, so the map is bounded by distinct keys seen.
79	     */
80	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
81	
82	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
83	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
84	
85	    /** Disposable email domains that are not accepted for an owner's email; a create with one is rejected. */
86	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
87	        "mailinator.com", "tempmail.com", "guerrillamail.com");
88	
89	    private final ClinicService clinicService;
90	
91	    private final OwnerMapper ownerMapper;
92	
93	    private final PetMapper petMapper;
94	
95	    private final VisitMapper visitMapper;
96	
97	    public OwnerRestControllerV1(ClinicService clinicService,
98	                                 OwnerMapper ownerMapper,
99	                                 PetMapper petMapper,
100	                                 VisitMapper visitMapper) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
110	        Collection<Owner> owners;
111	        if (lastName != null) {
112	            owners = this.clinicService.findOwnerByLastName(lastName);
113	        } else {
114	            owners = this.clinicService.findAllOwners();
115	        }
116	        if (owners.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
125	        return withOwner(ownerId, owner ->
126	            new ResponseEntity<>(buildOwnerDto(owner), HttpStatus.OK));
127	    }
128	
129	    /**
130	     * Look up the owner identified by {@code ownerId} and, when it exists, produce the response with
131	     * {@code onFound}; when no such owner exists, short-circuit with {@code 404 NOT_FOUND}. Centralizes
132	     * the fetch-and-guard shared by the single-owner endpoints so it is written once, not copied.
133	     */
134	    private <T> ResponseEntity<T> withOwner(Integer ownerId, Function<Owner, ResponseEntity<T>> onFound) {
135	        Owner owner = this.clinicService.findOwnerById(ownerId);
136	        if (owner == null) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        return onFound.apply(owner);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
145	        String idempotencyKey = currentIdempotencyKey();
146	        if (idempotencyKey != null) {
147	            Integer existingId = idempotentCreates.get(idempotencyKey);
148	            if (existingId != null) {
149	                Owner existing = this.clinicService.findOwnerById(existingId);
150	                if (existing != null) {
151	                    return new ResponseEntity<>(buildOwnerDto(existing), HttpStatus.OK);
152	                }
153	            }
154	        }
155	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
156	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
157	                && response.getBody() != null && response.getBody().getId() != null) {
158	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
159	        }
160	        return response;
161	    }
162	
163	    /**
164	     * The non-blank {@code Idempotency-Key} header on the current request, or {@code null} when the
165	     * header is absent or blank. Read from the ambient request rather than the handler signature so the
166	     * generated {@link OwnersApi#addOwner} contract stays unchanged.
167	     */
168	    private static String currentIdempotencyKey() {
169	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs) {
170	            String key = attrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
171	            if (key != null && !key.isBlank()) {
172	                return key;
173	            }
174	        }
175	        return null;
176	    }
177	
178	    /**
179	     * Run the create pipeline for a new owner from its submitted fields and return the response: the
180	     * fields are mapped, normalized and validated, the registration date is resolved, the per-day,
181	     * identity and per-city gates are applied, the derived registration attributes are
182	     * assigned and the owner is saved and audited, yielding {@code 201 CREATED} with the new owner and
183	     * its {@code Location}. A gate that trips short-circuits with its own status ({@code 400},
184	     * {@code 429} or {@code 409}) and no owner is created. This is the single place an owner is created;
185	     * {@link #addOwner} is the thin entry point that delegates here, so request-level concerns stay out
186	     * of the create pipeline.
187	     */
188	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
189	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
190	        if (!normalizeAndValidateFields(owner)) {
191	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
192	        }
193	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
194	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
195	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
196	        }
197	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
198	        owner.setRegistrationDate(registrationDate);
199	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
200	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
201	        }
202	        owner.setHouseholdId(householdId(owner));
203	        owner.setIdentityKey(identityKey(owner));
204	        if (isDuplicate(owner)) {
205	            return new ResponseEntity<>(HttpStatus.CONFLICT);
206	        }
207	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
208	        if (countOwnersInCity(owner.getCity()) >= 50) {
209	            return new ResponseEntity<>(HttpStatus.CONFLICT);
210	        }
211	        assignRegistrationAttributes(owner, sharesHousehold);
212	        this.clinicService.saveOwner(owner);
213	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
214	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
215	            owner.getMembershipNumber());
216	        HttpHeaders headers = new HttpHeaders();
217	        headers.setLocation(UriComponentsBuilder.newInstance()
218	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
219	        return new ResponseEntity<>(buildOwnerDto(owner), headers, HttpStatus.CREATED);
220	    }
221	
222	    /**
223	     * Canonicalize an incoming owner's submitted contact and address fields into their stored forms
224	     * and validate them, returning whether the owner may proceed to creation. On success the owner's
225	     * address, email (when supplied) and telephone are replaced with their normalized values. Returns
226	     * {@code false} - so the caller can reject the request with {@code 400 BAD_REQUEST} - when the
227	     * address is blank after normalization, a supplied email is not syntactically valid, the postcode
228	     * is not acceptable for the owner's city, or the telephone cannot form a valid E.164 number.
229	     */
230	    private boolean normalizeAndValidateFields(Owner owner) {
231	        if (!normalizeAddressFields(owner)) {
232	            return false;
233	        }
234	        if (owner.getEmail() != null) {
235	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
236	            if (!EMAIL_PATTERN.matcher(email).matches()) {
237	                return false;
238	            }
239	            if (isDisposableEmailDomain(email)) {
240	                return false;
241	            }
242	            owner.setEmail(email);
243	        }
244	        if (!isPostcodeValidForCity(owner)) {
245	            return false;
246	        }
247	        String telephone = normalizeTelephone(owner.getTelephone());
248	        if (telephone == null) {
249	            return false;
250	        }
251	        owner.setTelephone(telephone);
252	        return true;
253	    }
254	
255	    /**
256	     * Canonicalize an incoming owner's submitted address into its stored form and validate it,
257	     * returning whether the owner may proceed to creation. The structured fields are preferred when
258	     * present: when {@code addressLine1} is non-blank the structured lines are each normalized
259	     * ({@link #normalizeAddress}) and written back, and the flat {@code address} is set to the
260	     * composed value (the normalized addressLine1, with a single space and the normalized
261	     * addressLine2 appended when addressLine2 is present). Otherwise the flat {@code address} is
262	     * normalized and written back for backward compatibility. Returns {@code false} - so the caller
263	     * can reject the request with {@code 400 BAD_REQUEST} - when neither form supplies a non-blank
264	     * address. This is the single place the owner's address is read, canonicalized and written back,
265	     * mirroring the per-concern normalization the email, postcode and telephone steps each own.
266	     */
267	    private boolean normalizeAddressFields(Owner owner) {
268	        String line1 = normalizeAddress(owner.getAddressLine1());
269	        if (!line1.isEmpty()) {
270	            String line2 = normalizeAddress(owner.getAddressLine2());
271	            owner.setAddressLine1(line1);
272	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
273	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
274	            return true;
275	        }
276	        String address = normalizeAddress(owner.getAddress());
277	        if (address.isEmpty()) {
278	            return false;
279	        }
280	        owner.setAddress(address);
281	        return true;
282	    }
283	
284	    /**
285	     * Whether {@code email}'s domain (the part after the last '@') is on the disposable-domain
286	     * blocklist, compared case-insensitively. The email is already normalized to lower case by the
287	     * caller, so a simple membership test against {@link #DISPOSABLE_EMAIL_DOMAINS} suffices.
288	     */
289	    private static boolean isDisposableEmailDomain(String email) {
290	        int at = email.lastIndexOf('@');
291	        if (at < 0) {
292	            return false;
293	        }
294	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
295	    }
296	
297	    /**
298	     * Build the response DTO for a single owner, attaching the per-response derived flags that are
299	     * computed against the owner population rather than carried on the owner itself (currently the
300	     * {@code bulkSignupWarning}). Used by the single-owner read and create endpoints; the collection
301	     * listing intentionally omits these flags.
302	     */
303	    private OwnerDto buildOwnerDto(Owner owner) {
304	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
305	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
306	        return ownerDto;
307	    }
308	
309	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
310	    @Override
311	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
312	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
313	        if (currentOwner == null) {
314	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
315	        }
316	        currentOwner.setAddress(ownerFieldsDto.getAddress());
317	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
318	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
319	        currentOwner.setCity(ownerFieldsDto.getCity());
320	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
321	        currentOwner.setLastName(ownerFieldsDto.getLastName());
322	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
323	        String email = ownerFieldsDto.getEmail();
324	        if (email != null) {
325	            email = email.trim().toLowerCase(Locale.ROOT);
326	            if (!EMAIL_PATTERN.matcher(email).matches()) {
327	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
328	            }
329	        }
330	        currentOwner.setEmail(email);
331	        this.clinicService.saveOwner(currentOwner);
332	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
333	    }
334	
335	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
336	    @Transactional
337	    @Override
338	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
339	        return withOwner(ownerId, owner -> {
340	            owner.setDeleted(true);
341	            this.clinicService.saveOwner(owner);
342	            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
343	        });
344	    }
345	
346	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
347	    @Override
348	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
349	        Owner owner = this.clinicService.findOwnerById(ownerId);
350	        if (owner == null) {
351	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
352	        }
353	        HttpHeaders headers = new HttpHeaders();
354	        Pet pet = petMapper.toPet(petFieldsDto);
355	        owner.setId(ownerId);
356	        pet.setOwner(owner);
357	        pet.getType().setName(null);
358	        this.clinicService.savePet(pet);
359	        PetDto petDto = petMapper.toPetDto(pet);
360	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
361	            .buildAndExpand(pet.getId()).toUri());
362	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
363	    }
364	
365	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
366	    @Override
367	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
368	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
369	        if (currentOwner != null) {
370	            Pet currentPet = this.clinicService.findPetById(petId);
371	            if (currentPet != null) {
372	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
373	                currentPet.setName(petFieldsDto.getName());
374	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
375	                this.clinicService.savePet(currentPet);
376	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
377	            }
378	        }
379	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
380	    }
