410	
411	    /** Matches a well-formed postcode: exactly 4 digits. */
412	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
413	
414	    /**
415	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
416	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
417	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
418	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
419	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
420	     */
421	    private static boolean isPostcodeValidForCity(Owner owner) {
422	        String postcode = owner.getPostcode();
423	        if (postcode == null) {
424	            return true;
425	        }
426	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
427	            return false;
428	        }
429	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
430	        if (range == null) {
431	            return true;
432	        }
433	        int value = Integer.parseInt(postcode);
434	        return value >= range[0] && value <= range[1];
435	    }
436	
437	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
438	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
439	
440	    /**
441	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
442	     * code are kept when present; otherwise country code '+61' is assumed and a single
443	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
444	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
445	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
446	     * Returns {@code null} when the number cannot form a valid E.164 value.
447	     */
448	    private static String normalizeTelephone(String telephone) {
449	        if (telephone == null) {
450	            return null;
451	        }
452	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
453	        String e164;
454	        if (cleaned.startsWith("+")) {
455	            e164 = cleaned;
456	        } else {
457	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
458	            e164 = "+61" + national;
459	        }
460	        if (!E164_PATTERN.matcher(e164).matches()) {
461	            return null;
462	        }
463	        return hasValidNationalNumberLength(e164) ? e164 : null;
464	    }
465	
466	    /**
467	     * Whether the national number of a well-formed E.164 value has the length required for its
468	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
469	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
470	     */
471	    private static boolean hasValidNationalNumberLength(String e164) {
472	        String countryCode = Owner.countryCodeOf(e164);
473	        if (countryCode == null) {
474	            return true;
475	        }
476	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
477	    }
478	
479	    /**
480	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
481	     * code, membership number, household id, namesake count and household member count. Each is
482	     * derived from the owner's already-normalized fields and the existing owner population, so this
483	     * must run before the owner is saved, while the counts still exclude the owner being created.
484	     *
485	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
486	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
487	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
488	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
489	     */
490	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
491	        owner.setCustomerCode(generateCustomerCode(owner));
492	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
493	        owner.setHouseholdId(householdId(owner));
494	        owner.setNamesakeCount(countNamesakes(owner));
495	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
496	        owner.setMembershipLevelCap(membershipLevelCapForHousehold(owner));
497	        if (declaredMember) {
498	            owner.setPossibleDuplicate(false);
499	            owner.setPossibleDuplicateOf(null);
500	        } else {
501	            assignPossibleDuplicate(owner);
502	        }
503	    }
504	
505	    /**
506	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
507	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's postcode
508	     * and last-name {@link #soundex(String) Soundex} yet resolves to a different {@link #identityKey}.
509	     * Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf} to the
510	     * matching owner's id. Runs before save, against the existing owner population.
511	     */
512	    private void assignPossibleDuplicate(Owner owner) {
513	        Integer matchId = findPossibleDuplicateOf(owner);
514	        owner.setPossibleDuplicate(matchId != null);
515	        owner.setPossibleDuplicateOf(matchId);
516	    }
517	
518	    /**
519	     * The id of an existing owner that shares {@code owner}'s postcode and last-name
520	     * {@link #soundex(String) Soundex} but resolves to a different {@link #identityKey}, or
521	     * {@code null} when there is none. Because the telephone is part of the identity key, two owners
522	     * with the same last name and postcode but different telephones differ in key and so match here,
523	     * making the later a soft (possible) duplicate rather than a hard conflict. When several match,
524	     * the lowest id is returned. An owner without a postcode never matches.
525	     */
526	    private Integer findPossibleDuplicateOf(Owner owner) {
527	        String postcode = owner.getPostcode();
528	        if (postcode == null) {
529	            return null;
530	        }
531	        String soundex = soundex(owner.getLastName());
532	        String identityKey = owner.getIdentityKey();
533	        return this.clinicService.findAllOwners().stream()
534	            .filter(existing -> !existing.isDeleted())
535	            .filter(existing -> existing.getId() != null
536	                && postcode.equals(existing.getPostcode())
537	                && soundex(existing.getLastName()).equals(soundex)
538	                && !identityKey.equals(existing.getIdentityKey()))
539	            .map(Owner::getId)
540	            .min(Integer::compareTo)
541	            .orElse(null);
542	    }
543	
544	    /**
545	     * Build {@code owner}'s customer code '<REGION>-<HASH8>': REGION is the region code derived from
546	     * the owner's postcode ({@link Owner#getRegion()}) and HASH8 the first 8 upper-case hex
547	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
548	     * owner's last name (e.g. 'NSW-1A2B3C4D'). The identity is otherwise a pure function of the
549	     * region and the (telephone, last name) pair; only when the computed code collides with an
550	     * existing owner's customer code is it de-duplicated by appending '-<n>' with the smallest
551	     * {@code n} of 2 or more that makes it unique (e.g. 'NSW-1A2B3C4D-2').
552	     */
553	    private String generateCustomerCode(Owner owner) {
554	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
555	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
556	        String hash8 = Owner.sha256Hex(telephone + lastName).substring(0, 8);
557	        String base = owner.getRegion() + "-" + hash8;
558	        return deduplicateCustomerCode(base);
559	    }
560	
561	    /**
562	     * De-duplicate a computed customer code against the existing owner population: when {@code base}
563	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
564	     * {@code n} of 2 or more that yields a code no existing owner carries.
565	     */
566	    private String deduplicateCustomerCode(String base) {
567	        Set<String> existing = this.clinicService.findAllOwners().stream()
568	            .map(Owner::getCustomerCode)
569	            .filter(code -> code != null)
570	            .collect(java.util.stream.Collectors.toSet());
571	        if (!existing.contains(base)) {
572	            return base;
573	        }
574	        int n = 2;
575	        while (existing.contains(base + "-" + n)) {
576	            n++;
577	        }
578	        return base + "-" + n;
579	    }
580	
581	    /**
582	     * The number of existing owners registered in {@code city}, compared case-insensitively
583	     * with collapsed whitespace.
584	     */
585	    private int countOwnersInCity(String city) {
586	        String normalized = normalizeHouseholdField(city);
587	        return (int) this.clinicService.findAllOwners().stream()
588	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
589	            .count();
590	    }
591	
592	    /**
593	     * The effective registration date to store for a new owner: the date supplied on the request
594	     * when present, otherwise the current server date, in either case rolled forward to a business
595	     * day so it never falls on a weekend or public holiday (rolled forward to the next such day).
596	     * This single point of resolution is what every registration-date-derived value (the stored
597	     * date, the membership number's year segment, the per-day create-limit) is computed from.
598	     */
599	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
600	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
601	        return toBusinessDay(date);
602	    }
603	
604	    /**
605	     * The fixed list of public holidays that a registration date must not fall on. A date landing
606	     * on one of these is rolled forward, exactly as weekends are.
607	     */
608	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
609	        LocalDate.of(2026, 1, 1),
610	        LocalDate.of(2026, 1, 26),
611	        LocalDate.of(2026, 4, 25),
612	        LocalDate.of(2026, 12, 25),
613	        LocalDate.of(2026, 12, 28));
614	
615	    /**
616	     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
617	     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
618	     * unchanged.
619	     */
620	    private static LocalDate toBusinessDay(LocalDate date) {
621	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
622	                || PUBLIC_HOLIDAYS.contains(date)) {
623	            date = date.plusDays(1);
624	        }
625	        return date;
626	    }
627	
628	    /**
629	     * Build the membership number '<customerCode>-M<YY>' where YY is the
630	     * {@link #membershipYearSegment(LocalDate) fiscal-year segment} of the {@code registrationDate}
631	     * (e.g. 'NSW-1A2B3C4D-M27').
632	     */
633	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
634	        return customerCode + "-M" + membershipYearSegment(registrationDate);
635	    }
636	
637	    /**
638	     * The two-digit year segment stamped into a membership number: the last two digits of the
639	     * fiscal year (starting 1 July) that contains the business-day-adjusted {@code registrationDate},
640	     * zero-padded (e.g. a date of 2026-09-05 falls in fiscal year 2027 -> '27'). Shares the
641	     * fiscal-year rule with {@link Owner#getFiscalYear()} via {@link Owner#fiscalYear(LocalDate)}.
642	     */
643	    private static String membershipYearSegment(LocalDate registrationDate) {
644	        return String.format("%02d", Owner.fiscalYear(registrationDate) % 100);
645	    }
646	
647	    /**
648	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
649	     * last name, compared case-insensitively.
650	     */
651	    private int countNamesakes(Owner owner) {
652	        String firstName = normalizeHouseholdField(owner.getFirstName());
653	        String lastName = normalizeHouseholdField(owner.getLastName());
654	        return (int) this.clinicService.findAllOwners().stream()
655	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
656	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
657	            .count();
658	    }
659	
660	    /**
661	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
662	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
663	     * unusually high daily signup volume.
664	     */
665	    private boolean isBulkSignupWarning() {
666	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
667	    }
668	
669	    /** The number of existing owners whose registration date is {@code date}. */
670	    private int countOwnersRegisteredOn(LocalDate date) {
671	        return (int) this.clinicService.findAllOwners().stream()
672	            .filter(existing -> date.equals(existing.getRegistrationDate()))
673	            .count();
674	    }
675	
676	    /**
677	     * The single derived key all duplicate detection flows through: the lower-case hex SHA-256 of
678	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, formed from the
679	     * owner's already-normalized fields (the email is already lower-cased, the telephone already in
680	     * E.164 form, and the last name reduced to its {@link #soundex(String) Soundex} code). Because
681	     * the telephone is part of the key, two owners with the same last name and postcode but
682	     * different telephones resolve to different keys and are both allowed (the later one becoming a
683	     * possible duplicate rather than a hard conflict).
684	     */
685	    private static String identityKey(Owner owner) {
686	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
687	        String email = owner.getEmail() == null ? "" : owner.getEmail();
688	        String key = telephone + "|" + email + "|" + soundex(owner.getLastName());
689	        return Owner.sha256HexLower(key);
690	    }
691	
692	    /**
693	     * Whether {@code owner}'s {@link #identityKey} equals a non-deleted existing owner's, which is
694	     * the sole duplicate condition: the previously separate telephone, email and household checks -
695	     * including the household-duplicate check derived from the {@code householdId} - are now all
696	     * expressed through this one identity key, so only an exact key match is a duplicate and a create
697	     * that trips it is rejected with {@code 409 CONFLICT}. Soft-deleted owners are ignored.
698	     */
699	    private boolean isDuplicate(Owner owner) {
700	        String key = owner.getIdentityKey();
701	        return this.clinicService.findAllOwners().stream()
702	            .filter(existing -> !existing.isDeleted())
703	            .map(Owner::getIdentityKey)
704	            .filter(existing -> existing != null)
705	            .anyMatch(key::equals);
706	    }
707	
708	    /** Common street-type abbreviations expanded during address normalization. */
709	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
710	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
711	
712	    /**
713	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
714	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
715	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
716	     * string when {@code address} is null or blank after normalization.
717	     */
718	    private static String normalizeAddress(String address) {
719	        if (address == null) {
720	            return "";
721	        }
722	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
723	        if (collapsed.isEmpty()) {
724	            return "";
725	        }
726	        StringBuilder sb = new StringBuilder(collapsed.length());
727	        for (String token : collapsed.split(" ")) {
728	            if (sb.length() > 0) {
729	                sb.append(' ');
730	            }
731	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
732	        }
733	        return sb.toString();
734	    }
735	
736	    /**
737	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
738	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
739	     */
740	    private static String normalizeHouseholdField(String value) {
741	        if (value == null) {
742	            return "";
743	        }
744	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
745	    }
746	
747	    /**
748	     * The American Soundex code of {@code value}: the retained first letter followed by up to three
749	     * digits encoding the remaining consonants, right-padded with zeros to length four. Non-letters
750	     * are ignored, adjacent letters coding to the same digit (including when separated by 'H' or 'W')
751	     * are coded once, and vowels (with 'Y') act as separators. Returns the empty string when
752	     * {@code value} holds no letters. Phonetically similar last names share a code, which is what the
753	     * identity key and the possible-duplicate soft match compare on.
754	     */
755	    private static String soundex(String value) {
756	        if (value == null) {
757	            return "";
758	        }
759	        StringBuilder letters = new StringBuilder();
760	        for (char c : value.toCharArray()) {
761	            if (c < 128 && Character.isLetter(c)) {
762	                letters.append(Character.toUpperCase(c));
763	            }
764	        }
765	        if (letters.length() == 0) {
766	            return "";
767	        }
768	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
769	        char previous = soundexDigit(letters.charAt(0));
770	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
771	            char c = letters.charAt(i);
772	            if (c == 'H' || c == 'W') {
773	                continue;
774	            }
775	            char digit = soundexDigit(c);
776	            if (digit != '0' && digit != previous) {
777	                code.append(digit);
778	            }
779	            previous = digit;
780	        }
781	        while (code.length() < 4) {
782	            code.append('0');
783	        }
784	        return code.toString();
785	    }
786	
787	    /** The Soundex digit for an upper-case letter, or {@code '0'} for letters that are not coded. */
788	    private static char soundexDigit(char c) {
789	        switch (c) {
790	            case 'B': case 'F': case 'P': case 'V':
791	                return '1';
792	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
793	                return '2';
794	            case 'D': case 'T':
795	                return '3';
796	            case 'L':
797	                return '4';
798	            case 'M': case 'N':
799	                return '5';
800	            case 'R':
801	                return '6';
802	            default:
803	                return '0';
804	        }
805	    }
806	
807	    /**
808	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
809	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
810	     * key rather than re-derived from the underlying fields here, so the household is described in one
811	     * place and every household-keyed value stays consistent with it.
812	     */
813	    private List<Owner> findHousemates(Owner owner) {
814	        String householdId = householdId(owner);
815	        return this.clinicService.findAllOwners().stream()
816	            .filter(existing -> !existing.isDeleted())
817	            .filter(existing -> householdId(existing).equals(householdId))
818	            .toList();
819	    }
820	
821	    /**
822	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
823	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
824	     */
825	    private int countHouseholdMembers(Owner owner) {
826	        return findHousemates(owner).size() + 1;
827	    }
828	
829	    /**
830	     * The membership level ceiling for a newly registered {@code owner}, derived from the household it
831	     * joins: one above the current maximum {@link Owner#getMembershipLevel() membershipLevel} among the
832	     * existing housemates (owners sharing the same {@code householdId}), so a new owner's reported level
833	     * can never exceed one above the household's current best. Returns {@code null} - meaning no ceiling
834	     * applies - when the owner has no existing household member.
835	     */
836	    private Integer membershipLevelCapForHousehold(Owner owner) {
837	        OptionalInt maxLevel = findHousemates(owner).stream()
838	            .mapToInt(Owner::getMembershipLevel)
839	            .max();
840	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
841	    }
842	
843	    /**
844	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
845	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. It is the
846	     * first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode} (the empty
847	     * string standing in for a missing postcode), so housemates always resolve to the same value
848	     * regardless of registration order, and owners sharing a last name and postcode share it
849	     * automatically.
850	     */
851	    private static String householdId(Owner owner) {
852	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
853	        String key = normalizeHouseholdField(owner.getLastName()) + "|" + postcode;
854	        return Owner.sha256Hex(key).substring(0, 12);
855	    }
856	}
